int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int T;
    cin >> T;

    while (T--) {
        int N;
        cin >> N;
        vector<int> a(N);
        for (int i = 0; i < N; i++) cin >> a[i];

        int M;
        cin >> M;
        vector<int> b(M);
        for (int i = 0; i < M; i++) cin >> b[i];

        vector<int> ans;
        int i = 0, j = 0, carry = 0;

        while (i < N || j < M || carry) {
            int sum = carry;
            if (i < N) sum += a[i++];
            if (j < M) sum += b[j++];
            ans.push_back(sum % 10);
            carry = sum / 10;
        }

        for (int k = 0; k < ans.size(); k++) {
            if (k) cout << " ";
            cout << ans[k];
        }
        cout << "\n";
    }

    return 0;
}

