import sys
import heapq


def trap_rain_water(grid):
    m = len(grid)
    if m == 0:
        return 0
    n = len(grid[0])
    if n == 0 or m < 3 or n < 3:
        return 0

    visited = [[False] * n for _ in range(m)]
    heap = []
    for i in range(m):
        for j in range(n):
            if i == 0 or i == m - 1 or j == 0 or j == n - 1:
                heapq.heappush(heap, (grid[i][j], i, j))
                visited[i][j] = True

    dirs = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    water = 0

    while heap:
        h, x, y = heapq.heappop(heap)
        for dx, dy in dirs:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny]:
                visited[nx][ny] = True
                nh = grid[nx][ny]
                if nh < h:
                    water += h - nh
                heapq.heappush(heap, (max(h, nh), nx, ny))
    return water


def main():
    data = sys.stdin.read().split()
    idx = 0
    m = int(data[idx]); idx += 1
    n = int(data[idx]); idx += 1
    grid = []
    for i in range(m):
        row = [int(x) for x in data[idx:idx + n]]
        idx += n
        grid.append(row)
    res = trap_rain_water(grid)
    print(res)


if __name__ == '__main__':
    main()

