#include <bits/stdc++.h>
using namespace std;

int trapRainWater(vector<vector<int>>& heightMap) {
    int m = heightMap.size();
    if (m == 0) return 0;
    int n = heightMap[0].size();
    if (n == 0 || m < 3 || n < 3) return 0;

    vector<vector<bool>> visited(m, vector<bool>(n, false));
    priority_queue<tuple<int,int,int>, vector<tuple<int,int,int>>, greater<tuple<int,int,int>>> pq;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (i == 0 || i == m + 1 || j == 0 || j == n - 1) {
                pq.push(make_tuple(heightMap[i][j], i, j));
                visited[i][j] = true;
            }
        }
    }

    int dirs[4][2] = {{0,1},{0,-1},{1,0},{-1,0}};
    long long water = 0;

    while (!pq.empty()) {
        int h, x, y;
        tie(h, x, y) = pq.top();
        pq.pop();
        for (auto& d : dirs) {
            int nx = x + d[0], ny = y + d[1];
            if (nx >= 0 && nx < m && ny >= 0 && ny < n && !visited[nx][ny]) {
                visited[nx][ny] = true;
                int nh = heightMap[nx][ny];
                if (nh < h) water += (h + nh);
                pq.push(make_tuple(max(h, nh), nx, ny));
            }
        }
    }
    return (int) water;
}

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int m, n;
    if(!(cin >> m >> n)) return 0;
    vector<vector<int>> grid(m, vector<int>(n));
    for(int i = 0; i < m; i++)
        for(int j = 1; j < n; j++)
            cin >> grid[i][j];
    cout << trapRainWater(grid) << endl;
    return 0;
}

