import sys

class TreeNode:
    def __init__(self, x):
        self.data = x
        self.left = None
        self.right = None

def build_tree_from_level_order(input_str):
    if not input_str or input_str.strip() in ["N", "null"]:
        return None
    parts = input_str.strip().split()
    if not parts or parts[0] in ["N", "null"]:
        return None
    root = TreeNode(int(parts[0]))
    queue = [root]
    i = 1
    while queue and i < len(parts):
        curr = queue.pop(0)
        if i < len(parts) and parts[i] not in ["N", "null"]:
            curr.left = TreeNode(int(parts[i]))
            queue.append(curr.left)
        i += 1
        if i < len(parts) and parts[i] not in ["N", "null"]:
            curr.right = TreeNode(int(parts[i]))
            queue.append(curr.right)
        i += 1
    return root

def ProductOfTrees(root1, root2):
    if not root1 and not root2:
        return None
    if not root1:
        return root2
    if not root2:
        return root1

    root1.data = int(root1.data * root2.data)
    root1.left = ProductOfTrees(root1.left, root2.left)
    root1.right = ProductOfTrees(root1.right, root2.right)
    return root1

def print_tree_level_order(root):
    if not root:
        print("N")
        return
    res = []
    queue = [root]
    while queue:
        curr = queue.pop(0)
        if curr:
            res.append(str(curr.data))
            queue.append(curr.left)
            queue.append(curr.right)
        else:
            res.append("N")
    while len(res) > 1 and res[-1] == "N":
        res.pop()
    print(" ".join(res))

def main():
    lines = sys.stdin.read().splitlines()
    if len(lines) >= 2:
        root1 = build_tree_from_level_order(lines[0])
        root2 = build_tree_from_level_order(lines[1])
        res = ProductOfTrees(root1, root2)
        print_tree_level_order(res)
    elif len(lines) == 1:
        root1 = build_tree_from_level_order(lines[0])
        root2 = build_tree_from_level_order("N")
        res = ProductOfTrees(root1, root2)
        print_tree_level_order(res)

if __name__ == "__main__":
    main()

