}","js":"// ─── Kanban Task Manager — Complete Solution ───────────────────────────────

// Update .count badge for all 3 columns
function updateCounts() {
  ['todo', 'in-progress', 'done'].forEach(id => {
    const col = document.getElementById(id);
    if (!col) return;
    const cards = col.querySelectorAll('.task-list .task-card').length;
    const badge = col.querySelector('.count');
    if (badge) badge.textContent = String(cards);
  });
}

// Create a draggable .task-card with a .remove-btn
function createCard(text) {
  const card = document.createElement('div');
  card.className = 'task-card';
  card.draggable = true;
  card.setAttribute('draggable', 'true');

  const label = document.createElement('span');
  label.className = 'card-text';
  label.textContent = text;

  const btn = document.createElement('button');
  btn.className = 'remove-btn';
  btn.textContent = '✕';
  btn.addEventListener('click', () => {
    card.remove();
    updateCounts();
  });

  card.appendChild(label);
  card.appendChild(btn);

  // Drag events
  card.addEventListener('dragstart', (e) => {
    e.dataTransfer.setData('text/plain', text);
    card.classList.add('dragging');
    // Store reference to original card for real browser drag
    window._draggedCard = card;
  });

  card.addEventListener('dragend', () => {
    card.classList.remove('dragging');
    window._draggedCard = null;
  });

  return card;
}

// Add task from input to #todo column
function addTask() {
  const input = document.getElementById('task-input');
  if (!input) return;

  const text = input.value.trim();
  if (!text) return;  // Reject empty / whitespace input

  const list = document.querySelector('#todo .task-list');
  if (!list) return;

  list.appendChild(createCard(text));
  input.value = '';  // Clear input after add
  updateCounts();
}

// Setup drag-and-drop on all .task-list elements
function setupDragDrop() {
  document.querySelectorAll('.task-list').forEach(list => {
    list.addEventListener('dragover', (e) => {
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
      list.classList.add('drag-over');
    });

    list.addEventListener('dragleave', () => {
      list.classList.remove('drag-over');
    });

    list.addEventListener('drop', (e) => {
      e.preventDefault();
      list.classList.remove('drag-over');

      // Use stored reference (works with Playwright dragTo)
      const dragged = window._draggedCard;
      if (dragged && dragged.parentElement !== list) {
        list.appendChild(dragged);
        // Rebuild remove button handler after move
        const btn = dragged.querySelector('.remove-btn');
        if (btn) {
          const newBtn = btn.cloneNode(true);
          newBtn.addEventListener('click', () => {
            dragged.remove();
            updateCounts();
          });
          btn.replaceWith(newBtn);
        }
        updateCounts();
      } else {
        // Fallback: recreate card from text data
        const text = e.dataTransfer.getData('text/plain');
        if (text && text.trim()) {
          list.appendChild(createCard(text));
          updateCounts();
        }
      }
    });
  });
}

// ─── Init ──────────────────────────────────────────────────────────────────
function init() {
  const addBtn = document.getElementById('add-btn');
  const input  = document.getElementById('task-input');

  if (addBtn) addBtn.addEventListener('click', addTask);

  if (input) {
    input.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') addTask();
    });
  }

  setupDragDrop();
  updateCounts();
}

// DOMContentLoaded guarantee (fixes iframe timing issues)
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', init);
} else {
  init();
}
"}

