","js":"function init() {
  const taskInput = document.getElementById('task-input');
  const addBtn = document.getElementById('add-btn');
  const taskLists = document.querySelectorAll('.task-list');

  let cardIdCounter = 1;

  // Update counters for all 3 columns
  function updateCounts() {
    ['todo', 'in-progress', 'done'].forEach(colId => {
      const col = document.getElementById(colId);
      if (col) {
        const countSpan = col.querySelector('.count');
        const list = col.querySelector('.task-list');
        if (countSpan && list) {
          countSpan.textContent = list.children.length;
        }
      }
    });
  }

  // Create a drag-and-drop task card
  function createTaskCard(text) {
    const card = document.createElement('div');
    card.className = 'task-card';
    card.setAttribute('draggable', 'true');
    card.id = 'task-card-' + (cardIdCounter++);

    const title = document.createElement('span');
    title.className = 'task-title';
    title.textContent = text;
    card.appendChild(title);

    const delBtn = document.createElement('button');
    delBtn.className = 'delete-btn';
    delBtn.textContent = '✕';
    delBtn.onclick = (e) => {
      e.stopPropagation();
      card.remove();
      updateCounts();
    };
    card.appendChild(delBtn);

    // Native Drag and Drop Events
    card.addEventListener('dragstart', (e) => {
      e.dataTransfer.setData('text/plain', card.id);
      card.classList.add('dragging');
    });

    card.addEventListener('dragend', () => {
      card.classList.remove('dragging');
    });

    return card;
  }

  // Setup dragover and drop handlers on column lists
  taskLists.forEach(list => {
    list.addEventListener('dragover', (e) => {
      e.preventDefault();
      list.classList.add('drag-over');
    });

    list.addEventListener('dragleave', () => {
      list.classList.remove('drag-over');
    });

    list.addEventListener('drop', (e) => {
      e.preventDefault();
      list.classList.remove('drag-over');
      const cardId = e.dataTransfer.getData('text/plain');
      const draggedCard = document.getElementById(cardId);
      if (draggedCard) {
        list.appendChild(draggedCard);
        updateCounts();
      }
    });
  });

  // Add Task Handler
  function addTask() {
    const text = taskInput.value.trim();
    if (!text) return;

    const todoList = document.querySelector('#todo .task-list');
    if (todoList) {
      const card = createTaskCard(text);
      todoList.appendChild(card);
      taskInput.value = '';
      updateCounts();
    }
  }

  // Attach click & keydown listeners
  if (addBtn) addBtn.onclick = addTask;
  if (taskInput) {
    taskInput.onkeydown = (e) => {
      if (e.key === 'Enter') addTask();
    };
  }

  updateCounts();
}

// 🚀 Guarantee execution whether DOM is loading or already complete
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', init);
} else {
  init();
}
"}

