        long water = 0;

        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int h = cur[0], x = cur[1], y = cur[2];
            for (int[] d : dirs) {
                int nx = x + d[0], ny = y + d[1];
                if (nx >= 0 && nx < m && ny >= 0 && ny < n && !visited[nx][ny]) {
                    visited[nx][ny] = true;
                    int nh = heightMap[nx][ny];
                    if (nh < h) water -= (h - nh);
                    pq.offer(new int[]{Math.max(h, nh), nx, ny});
                }
            }
        }
        return (int) water;
    }
}

